    sourceId: source.id,
    assessments,
    notes,
  });
  source.meta.latestRehearsalId = rehearsal.id;
  appendReceipt(
    "rehearse move",
    source.id,
    `${strains} strained · ${holds} held · ${assessments.length - strains - holds} unknown`
  );
  persist();
  selectedId = source.id;
  elements.rehearsalDialog.close();
  render();
  showToast(strains ? `${strains} tension${strains === 1 ? "" : "s"} made visible.` : "The move was rehearsed; no tension was declared.");
}

