function loadState() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return createFreshWorld();
    return sanitizeImportedWorld(JSON.parse(raw));
  } catch (error) {
    window.setTimeout(() => showToast(`A fresh surface was opened: ${error.message}`), 300);
    return createFreshWorld();
  }
}

function persist() {
  state.updatedAt = nowIso();
  elements.saveState.classList.add("is-saving");
  elements.saveState.querySelector("span:last-child").textContent = "Holding…";
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    window.clearTimeout(saveTimer);
    saveTimer = window.setTimeout(() => {
      elements.saveState.classList.remove("is-saving");
      elements.saveState.querySelector("span:last-child").textContent = "Held here";
    }, 260);
  } catch (error) {
    elements.saveState.classList.remove("is-saving");
    elements.saveState.querySelector("span:last-child").textContent = "In memory only";
    showToast("Browser storage is unavailable. Export to carry this world forward.");
  }
}

function noteVisit() {
  const today = dayKey(new Date());
  if (!state.visits.includes(today)) {
    state.visits.push(today);
    appendReceipt("return to world", state.worldId, `The hand returned on ${today}.`);
    persist();
  }
}

function exportWorld() {
  const envelope = {
    format: "tendora-world",
    exportedAt: nowIso(),
    seal: checksum(JSON.stringify(state)),
    world: state,
  };
  const blob = new Blob([JSON.stringify(envelope, null, 2)], { type: "application/json" });
  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  link.href = url;
  link.download = `the-hand-remains-${dayKey(new Date())}.json`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
  showToast("A portable world was made. Keep the JSON anywhere you trust.");
}

