  } catch (error) {
    showToast(`Import refused: ${error.message}`);
  } finally {
    elements.importFile.value = "";
  }
}

function saveHandoff(event) {
  event.preventDefault();
  const nextMove = elements.handoffInput.value.trim();
  if (nextMove === state.nextMove) {
    showToast("That thread is already held.");
    return;
  }
  state.nextMove = nextMove.slice(0, 280);
  appendReceipt("leave handoff", state.worldId, state.nextMove || "The next hand was left an open surface.");
  persist();
  renderHeader();
  showToast("The next hand will find this thread.");
}

